-- VENDOR: the auth tables are generated by better-auth 1.7.14 getMigrations().compileMigrations() for emailAndPassword, jwt() and @better-auth/mcp mcp() with plural modelNames; regenerate them when auth options change
create table "users" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "sessions" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "users" ("id") on delete cascade);

create table "accounts" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "users" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table "verifications" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create index "sessions_userId_idx" on "sessions" ("userId");

create index "accounts_userId_idx" on "accounts" ("userId");

create index "verifications_identifier_idx" on "verifications" ("identifier");

create table "jwks" ("id" text not null primary key, "publicKey" text not null, "privateKey" text not null, "createdAt" timestamptz not null, "expiresAt" timestamptz, "alg" text, "crv" text);

create table "oauthClients" ("id" text not null primary key, "clientId" text not null unique, "clientSecret" text, "clientDiscoveryId" text, "disabled" boolean, "skipConsent" boolean, "enableEndSession" boolean, "subjectType" text, "scopes" jsonb, "clientCredentialsScopes" jsonb, "userId" text references "users" ("id") on delete cascade, "createdAt" timestamptz, "updatedAt" timestamptz, "name" text, "uri" text, "icon" text, "contacts" jsonb, "tos" text, "policy" text, "softwareId" text, "softwareVersion" text, "softwareStatement" text, "redirectUris" jsonb not null, "postLogoutRedirectUris" jsonb, "backchannelLogoutUri" text, "backchannelLogoutSessionRequired" boolean, "tokenEndpointAuthMethod" text, "applicationType" text, "jwks" text, "jwksUri" text, "grantTypes" jsonb, "responseTypes" jsonb, "requirePKCE" boolean, "dpopBoundAccessTokens" boolean, "referenceId" text, "metadata" jsonb);

create table "oauthResources" ("id" text not null primary key, "identifier" text not null unique, "name" text not null, "accessTokenTtl" integer, "refreshTokenTtl" integer, "signingAlgorithm" text, "signingKeyId" text, "allowedScopes" jsonb, "customClaims" jsonb, "dpopBoundAccessTokensRequired" boolean, "disabled" boolean, "createdAt" timestamptz, "updatedAt" timestamptz, "policyVersion" integer, "metadata" jsonb);

create table "oauthClientResources" ("id" text not null primary key, "clientId" text not null references "oauthClients" ("clientId") on delete cascade, "resourceId" text not null references "oauthResources" ("identifier") on delete cascade, "metadata" jsonb, "createdAt" timestamptz);

create table "oauthRefreshTokens" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClients" ("clientId") on delete cascade, "sessionId" text references "sessions" ("id") on delete set null, "userId" text not null references "users" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "rotatedAt" timestamptz, "rotationReplayResponse" text, "rotationReplayExpiresAt" timestamptz, "authTime" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);

create table "oauthAccessTokens" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClients" ("clientId") on delete cascade, "sessionId" text references "sessions" ("id") on delete set null, "userId" text references "users" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "refreshId" text references "oauthRefreshTokens" ("id") on delete cascade, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);

create table "oauthConsents" ("id" text not null primary key, "clientId" text not null references "oauthClients" ("clientId") on delete cascade, "userId" text references "users" ("id") on delete cascade, "referenceId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "scopes" jsonb not null, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);

create table "oauthClientAssertions" ("id" text not null primary key, "expiresAt" timestamptz not null);

create index "oauthClients_userId_idx" on "oauthClients" ("userId");

create index "oauthClientResources_clientId_idx" on "oauthClientResources" ("clientId");

create index "oauthClientResources_resourceId_idx" on "oauthClientResources" ("resourceId");

create index "oauthRefreshTokens_clientId_idx" on "oauthRefreshTokens" ("clientId");

create index "oauthRefreshTokens_sessionId_idx" on "oauthRefreshTokens" ("sessionId");

create index "oauthRefreshTokens_userId_idx" on "oauthRefreshTokens" ("userId");

create index "oauthRefreshTokens_authorizationCodeId_idx" on "oauthRefreshTokens" ("authorizationCodeId");

create index "oauthAccessTokens_clientId_idx" on "oauthAccessTokens" ("clientId");

create index "oauthAccessTokens_sessionId_idx" on "oauthAccessTokens" ("sessionId");

create index "oauthAccessTokens_userId_idx" on "oauthAccessTokens" ("userId");

create index "oauthAccessTokens_authorizationCodeId_idx" on "oauthAccessTokens" ("authorizationCodeId");

create index "oauthAccessTokens_refreshId_idx" on "oauthAccessTokens" ("refreshId");

create index "oauthConsents_clientId_idx" on "oauthConsents" ("clientId");

create index "oauthConsents_userId_idx" on "oauthConsents" ("userId");

create unique index "oauthClientResources_clientId_resourceId_uidx" on "oauthClientResources" ("clientId", "resourceId");

create table "todos" (
  "id" uuid primary key default gen_random_uuid(),
  "ownerId" text not null references "users" ("id") on delete cascade,
  "title" text not null check (char_length("title") between 1 and 200),
  "completed" boolean not null default false,
  "createdAt" timestamptz not null
);

create index "todos_ownerId_createdAt_idx" on "todos" ("ownerId", "createdAt");
